async () => {
  const searches = await Promise.all([
    connecta.search({ query: "list organizations projects", safety: "readOnly", includeSchemas: "compact", limit: 100 }),
    connecta.search({ query: "analytics project organizations", safety: "readOnly", includeSchemas: "compact", limit: 100 })
  ]);
  const merged = [];
  const seen = new Set();
  for (const s of searches) for (const t of s.tools) if (!seen.has(t.address)) { seen.add(t.address); merged.push(t); }
  const orgTools = merged.filter(t => /organization/i.test((t.address || "") + " " + (t.description || "")));
  if (!orgTools.length) throw new Error("No organization-listing tool found");
  const desc = await connecta.describe({ addresses: orgTools.slice(0, 20).map(t => t.address) });
  const detailed = desc.tools;
  const flattenKeys = obj => {
    const out = [];
    const walk = (x, path) => {
      if (!x || typeof x !== "object") return;
      for (const [k,v] of Object.entries(x)) {
        const p = path ? path + "." + k : k;
        if (!["description","title","examples","default"].includes(k)) out.push(p);
        walk(v,p);
      }
    };
    walk(obj,"");
    return out;
  };
  let chosen, projectPath;
  for (const t of detailed) {
    const paths = flattenKeys(t.inputSchema || t.schema || {});
    const p = paths.find(x => /(^|\.)(project(_?id|_?key|_?name)?)(\.|$)/i.test(x));
    if (p && /list|organization/i.test((t.address || "") + " " + (t.description || ""))) {
      chosen = t; projectPath = p; break;
    }
  }
  if (chosen) {
    const key = projectPath.split(".").filter(x => !["properties","items"].includes(x)).pop();
    return await connecta.call(chosen.address, { [key]: "mxp_eval_42" });
  }
  const projectsTool = detailed.find(t =>
    /project/i.test((t.address || "") + " " + (t.description || "")) &&
    /list|organization/i.test((t.address || "") + " " + (t.description || ""))
  );
  if (projectsTool) {
    const keys = [...(projectsTool.requiredInputKeys || []), ...(projectsTool.inputKeys || [])];
    const key = keys.find(k => /project/i.test(k));
    if (key) return await connecta.call(projectsTool.address, { [key]: "mxp_eval_42" });
  }
  const noArgOrg = detailed.find(t =>
    /list/i.test((t.address || "") + " " + (t.description || "")) &&
    (t.requiredInputKeys || []).length === 0
  );
  if (!noArgOrg) throw new Error("No callable organization listing tool");
  return await connecta.call(noArgOrg.address, {});
}

